def _to_linecol(self) -> tuple[int, int]:
    if self.idx >= len(self):
        return len(self.splitlines()), 0

    # Count line breaks in the text before the current character. A CRLF
    # pair is one break (and its CR is not part of the column), so the
    # result is the same as for LF-only input.
    prefix = self[: self.idx]
    if self.current == "\n" and prefix.endswith("\r"):
        prefix = prefix[:-1]
    lines = prefix.replace("\r\n", "\n").replace("\r", "\n").split("\n")

    return len(lines), len(lines[-1])

